create function public.business_quality_dashboard(p_hash text,p_slug text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare a public.business_accounts%rowtype;today date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;incidents jsonb;actions jsonb;incident_severity jsonb;quality_severity jsonb;incident_count integer;open_incidents integer;stopped_count integer;open_nonconformances integer;overdue_actions integer;critical_incidents integer;
begin
 a:=public.business_assert_session(p_hash,p_slug,false);
 perform public.business_assert_kind(a.tenant_id,'safety_incidents');perform public.business_assert_kind(a.tenant_id,'quality_nonconformances');perform public.business_assert_kind(a.tenant_id,'corrective_actions');
 select count(*)::integer,count(*) filter(where status in ('draft','returned'))::integer,count(*) filter(where r.work_stopped)::integer,count(*) filter(where severity='critical' and status not in ('posted','cancelled'))::integer into incident_count,open_incidents,stopped_count,critical_incidents from public.business_safety_incidents r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'safety_incidents','read',to_jsonb(r));
 select count(*) filter(where status not in ('posted','cancelled'))::integer into open_nonconformances from public.business_quality_nonconformances r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'quality_nonconformances','read',to_jsonb(r));
 select count(*) filter(where status not in ('posted','cancelled') and due_on<today)::integer into overdue_actions from public.business_corrective_actions r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'corrective_actions','read',to_jsonb(r));
 select coalesce(jsonb_object_agg(s.severity,s.n),'{}'::jsonb) into incident_severity from (select r.severity,count(*)::integer n from public.business_safety_incidents r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'safety_incidents','read',to_jsonb(r)) group by r.severity)s;
 select coalesce(jsonb_object_agg(s.severity,s.n),'{}'::jsonb) into quality_severity from (select r.severity,count(*)::integer n from public.business_quality_nonconformances r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'quality_nonconformances','read',to_jsonb(r)) group by r.severity)s;
 with recent as (select r.id,'safety_incidents'::text kind,r.code,r.name,r.status state,r.incident_date date from public.business_safety_incidents r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'safety_incidents','read',to_jsonb(r)) union all select r.id,'quality_nonconformances',r.code,r.name,r.status,r.detected_on from public.business_quality_nonconformances r where r.tenant_id=a.tenant_id and public.business_access_allowed(a.id,'quality_nonconformances','read',to_jsonb(r)) order by date desc limit 12)
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'kind',q.kind,'code',q.code,'name',q.name,'state',q.state,'date',q.date) order by q.date desc),'[]'::jsonb) into incidents from recent q;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'code',q.code,'name',q.name,'dueOn',q.due_on,'state',q.status) order by q.due_on),'[]'::jsonb) into actions from (select r.id,r.code,r.name,r.due_on,r.status from public.business_corrective_actions r where r.tenant_id=a.tenant_id and r.status not in ('posted','cancelled') and r.due_on<today and public.business_access_allowed(a.id,'corrective_actions','read',to_jsonb(r)) order by r.due_on limit 12)q;
 return jsonb_build_object('asOf',today,'totals',jsonb_build_object('incidents',incident_count,'openIncidents',open_incidents,'workStopped',stopped_count,'criticalOpen',critical_incidents,'openNonconformances',coalesce(open_nonconformances,0),'overdueActions',coalesce(overdue_actions,0)),'incidentSeverity',incident_severity,'qualitySeverity',quality_severity,'recent',incidents,'overdue',actions);
end $$;
revoke all on function public.business_quality_dashboard(text,text) from public,anon,authenticated,service_role;
grant execute on function public.business_quality_dashboard(text,text) to service_role;
